package practice;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Future;

/**
 * Downloads the pages of a paginated report in parallel: one task per page, run on a pool, and
 * the results put back in page order.
 */
public class PageFetcher {

    /** Fetches one page of the report; pages are numbered from 1. */
    public interface Client {
        String fetch(int page);
    }

    private final Client client;

    public PageFetcher(Client client) {
        this.client = client;
    }

    public List<String> fetchAll(int pageCount, ExecutorService pool) throws Exception {
        List<String> pages = new ArrayList<>();
        for (Future<String> page : pool.invokeAll(tasks(pageCount))) {
            pages.add(page.get());
        }
        return pages;
    }

    /** One task per page, 1 to pageCount, in page order. */
    List<Callable<String>> tasks(int pageCount) {
        List<Callable<String>> tasks = new ArrayList<>();
        for (int page = 1; page <= pageCount; page++) {
            int p = page;
            tasks.add(() -> client.fetch(p));
        }
        return tasks;
    }
}

package practice;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            List<Integer> requested = Collections.synchronizedList(new ArrayList<>());
            PageFetcher fetcher = new PageFetcher(page -> {
                requested.add(page);
                return "orders page " + page;
            });
            System.out.println("tasks for 3 pages: " + fetcher.tasks(3).size());
            ExecutorService pool = Executors.newFixedThreadPool(2);
            try {
                List<String> pages = fetcher.fetchAll(3, pool);
                for (String page : pages) {
                    System.out.println("got: " + page);
                }
            } finally {
                pool.shutdownNow();
            }
            Collections.sort(requested);
            System.out.println("pages requested: " + requested);
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

